// ─── Batch 5 | Build Comms Payload ─────────────────────────────────────────────
// Pre-builds all outbound communication content in one pass:
//   • Email subjects + bodies (interpolated from Postgres client templates)
//   • Slack card color (green = QUALIFIED, orange = REJECTED)
// Templates support {candidate_name}, {role}, {score}, {disposition} placeholders.
// Fallback content used when Postgres templates are empty.
// Re-sets candidate customData so error handler has context if this sub-workflow fails.
// ─────────────────────────────────────────────────────────────────────────────

const item = $input.first().json;

// ── Re-set execution context (customData does not cross sub-workflow boundaries) ──
$execution.customData.set('candidate_name',  item.candidateName  ?? 'N/A');
$execution.customData.set('candidate_email', item.candidateEmail ?? 'N/A');
$execution.customData.set('stage',           'comms_routing');

const vars = {
  candidate_name: item.candidateName,
  role:           item.roleApplied,
  score:          String(item.compositeScore),
  threshold:      String(item.threshold ?? 60),
  client:         item.clientName ?? item.client_slug ?? '',
  disposition:    item.disposition,
  signal:         item.overallSignal
};

// Uses word-char pattern for placeholder keys (all keys are word chars: a-z, 0-9, _)
// This avoids negated character class which triggers expression validator false-positive.
const interpolate = (tmpl) =>
  (tmpl ?? '').replace(/\{(\w+)\}/g, (_, k) => vars[k] ?? ('{' + k + '}'));

// ── Success email ──
const successSubject = interpolate(item.successSubject) ||
  `Your application for ${item.roleApplied} — Next Steps`;
const successBody = interpolate(item.successBody) ||
  `Dear ${item.candidateName},\n\nThank you for applying for the ${item.roleApplied} position.\n\n` +
  `We have reviewed your application and are pleased to move forward. ` +
  `Our team will be in touch shortly with details on the next steps.\n\n` +
  `Best regards,\n${item.clientName ?? 'Our Recruitment Team'}`;

// ── Rejection email ──
const rejectSubject = interpolate(item.rejectSubject) ||
  `Your application for ${item.roleApplied} — Update`;
const rejectBody = interpolate(item.rejectBody) ||
  `Dear ${item.candidateName},\n\nThank you for your interest in the ${item.roleApplied} position ` +
  `and for taking the time to apply.\n\n` +
  `After careful review, we have decided to move forward with candidates whose ` +
  `experience more closely matches our current requirements.\n\n` +
  `We appreciate your interest and wish you every success in your search.\n\n` +
  `Best regards,\n${item.clientName ?? 'Our Recruitment Team'}`;

// ── Slack card color ──
const slackColor = item.disposition === 'QUALIFIED' ? '#36a64f' : '#e8882a';

// ── Slack-escaped variants (F-04: prevents mrkdwn injection via <url|text> syntax) ──
// Candidate-controlled fields must be escaped before interpolation into Slack messages.
const escapeSlack = (v) =>
  String(v ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const _slackSafeName   = escapeSlack(item.candidateName);
const _slackSafeRole   = escapeSlack(item.roleApplied);
const _slackSafeClient = escapeSlack(item.clientName ?? item.client_slug ?? '');
const _slackSafeSignal = escapeSlack(item.overallSignal ?? '');
const _slackSafeScore  = String(item.compositeScore ?? 0); // numeric — no escaping needed

return [{
  json: {
    ...item,
    _slackSafeName,
    _slackSafeRole,
    _slackSafeClient,
    _slackSafeSignal,
    _slackSafeScore,
    _comms: { successSubject, successBody, rejectSubject, rejectBody, slackColor }
  }
}];

// ─── Batch 5 | QUALIFIED Output ──────────────────────────────────────────────────
// Terminal node for the QUALIFIED path (score ≥ threshold).
// Reconstructs full scored payload, adds comms flags, strips internal fields.
// ClickUp node has onError: 'continueRegularOutput' — check for error before
// reporting task as created (prevents false positives in audit log).
// ─────────────────────────────────────────────────────────────────────────────

const cuResult = $input.first().json;
const base     = $('Build Comms Payload').first().json;
const { _comms, ...cleanItem } = base;

// ClickUp success: no error field AND has a task ID
const cuTaskId       = cuResult.id ?? cuResult.task?.id ?? null;
const clickUpCreated = !cuResult.error && cuTaskId != null;

return [{
  json: {
    ...cleanItem,
    slackNotified:      true,
    gmailSent:          true,
    emailType:          'success',
    clickUpTaskCreated: clickUpCreated,
    clickUpTaskId:      clickUpCreated ? String(cuTaskId) : '',
    commsCompletedAt:   new Date().toISOString()
  }
}];

// ─── Batch 5 | REJECTED Output ──────────────────────────────────────────────────
// Terminal node for the REJECTED path (score < threshold).
// Reconstructs full scored payload, adds comms flags, strips internal fields.
// No ClickUp task created for rejected candidates.
// ─────────────────────────────────────────────────────────────────────────────

const base = $('Build Comms Payload').first().json;
const { _comms, ...cleanItem } = base;

return [{
  json: {
    ...cleanItem,
    slackNotified:      true,
    gmailSent:          true,
    emailType:          'rejection',
    clickUpTaskCreated: false,
    commsCompletedAt:   new Date().toISOString()
  }
}];
